def _node_exe() -> str | None:
    bundled = BUNDLED_NODE / "node.exe"
    if bundled.exists():
        return str(bundled)
    found = shutil.which("node")
    if found:
        return found
    for candidate in (
        Path(os.environ.get("ProgramFiles", "")) / "nodejs" / "node.exe",
        Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "node" / "node.exe",
    ):
        if candidate.exists():
            return str(candidate)
    return None


def _npm_exe() -> str | None:
    node = _node_exe()
    if node:
        sibling = Path(node).parent / ("npm.cmd" if os.name == "nt" else "npm")
        if sibling.exists():
            return str(sibling)
    return shutil.which("npm.cmd" if os.name == "nt" else "npm")


def _build_frontend_with_node(*, hide: bool) -> None:
    """无 npm 时直接用 node 调用本地 tsc + vite（适配 Cursor 等精简 Node 环境）。"""
    node = _node_exe()
    if not node:
        raise RuntimeError("未找到 node，请安装 Node.js 或将 node 加入 PATH")
    tsc = FRONTEND / "node_modules" / "typescript" / "bin" / "tsc"
    vite = FRONTEND / "node_modules" / "vite" / "bin" / "vite.js"
    if not tsc.exists() or not vite.exists():
        raise RuntimeError("请先在前端目录执行 npm install（或复制完整 node_modules）")
    _run_cmd([node, str(tsc)], FRONTEND, hide=hide)
    _run_cmd([node, str(vite), "build"], FRONTEND, hide=hide)

def _ensure_frontend_built(*, hide: bool) -> None:
    dist = FRONTEND / "dist" / "index.html"
    if dist.exists():
        return
    _say("[build] 首次启动，正在构建前端（仅一次）…", silent=hide)
    npm = _npm_exe()
    if npm and not (FRONTEND / "node_modules").exists():
        _run_cmd([npm, "install"], FRONTEND, hide=hide)
    if npm:
        _run_cmd([npm, "run", "build"], FRONTEND, hide=hide)
    else:
        _build_frontend_with_node(hide=hide)

